import{z as l,x as A,o as E,c as s,q as i,j as r,D as e,d as n,s as o,S as p}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"UIP 与 CIP","description":"","frontmatter":{"title":"UIP 与 CIP","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/uip-and-cip.md","filePath":"econ/uip-and-cip.md","lastUpdated":1791063341000}'),B={name:"econ/uip-and-cip.md"};function P(d,a,C,I,c,m){const t=A("Mermaid");return E(),s("div",null,[a[2]||(a[2]=i('<h1 id="uip-与-cip" tabindex="-1">UIP 与 CIP <a class="header-anchor" href="#uip-与-cip" aria-label="Permalink to &quot;UIP 与 CIP&quot;">​</a></h1><div class="epigraph"><p>抛补平价是即期、远期与两个货币市场之间的复制；无抛补把远期换成对未来即期的期望。把两句话写成一句，后面的谜题都从这里开始。</p><footer>—— Keynes, A Tract on Monetary Reform, 1923</footer></div><p><a href="/econ/balassa-samuelson">上一课</a>处理的是货物相对价格与实际汇率的水平。本课的缺口是资产平价：利率差如何接到汇率。CIP 是有远期对冲的无套利；UIP 是无对冲的期望假说。实证、远期溢价之谜、交叉货币基差一律交给<a href="/quant/irp">量化栏的利率平价</a>，本课不编基差数字，也不重写限价簿。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PPP 把 \\(E\\) 接到物价；宏观政策还要把 \\(i\\) 接到 \\(i^*\\)。凯恩斯在《货币改革论》里已经把远期升贴水与利率差绑在一起。缺口是分开两句。CIP：在可兑换存款与可交割远期上，</p> \\[F=S\\frac{1+i}{1+i^*}, \\]<p>复制成立则无超额无风险收益。UIP：把 \\(F\\) 换成 \\(\\mathbb{E}[S_T]\\)，利率差等于预期贬值。CIP 是工具集足够时的会计；UIP 是风险溢价为零（或风险中性）的假说。把银行屏幕上的远期当成「市场预测」，是把 CIP 误读成 UIP。</p><p>上一课停在货物相对价格。本课换资产平价，但不做量化栏的回归与基差。Fama 斜率、危机后交叉货币基差一律见 <code>/quant/irp</code>。蒙代尔下一课用 UIP 的退化 \\(i=i^*\\)，需要本课先把两句话拆开。</p><p><span class="marginnote">宏观教学常写 \\(i=i^*+\\mathbb{E}\\Delta e\\)。那是 UIP。钉住且可信时 \\(\\mathbb{E}\\Delta e=0\\)，于是 \\(i=i^*\\)，接到蒙代尔。CIP 不要求对未来即期下注，只要求远期报价与利差对齐。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>宏观主干只保留定义与制度含义。完全资本流动加 UIP，本国利率政策必须承认 \\(\\mathbb{E}\\Delta e\\)；完全流动加 CIP，抛补回报被钉死，不能靠「无风险套息」当政策工具。风险溢价、中介约束、不可兑换，使市场报价偏离这两条——那是量化栏的对象：Fama 回归、危机后基差，本课不检验、不报数。</p>',11)),(E(),r(p,null,{default:e(()=>[o(t,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20CIP%5B%22CIP%EF%BC%9A%E8%BF%9C%E6%9C%9F%E5%A4%8D%E5%88%B6%22%5D%20--%3E%20ARB%5B%22%E6%97%A0%E5%A5%97%E5%88%A9%E4%BC%9A%E8%AE%A1%22%5D%0A%20%20UIP%5B%22UIP%EF%BC%9AE%5BS_T%5D%20%E6%9B%BF%E6%8D%A2%20F%5D%20--%3E%20HYP%5B%E6%9C%9F%E6%9C%9B%E5%81%87%E8%AF%B4%22%5D%0A%20%20ARB%20--%3E%20MF%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9Ai%20%E4%B8%8E%20E%20%E7%9A%84%E5%88%B6%E5%BA%A6%E5%88%86%E5%8F%89%22%5D%0A%20%20HYP%20--%3E%20MF%0A%20%20EMP%5B%22%E5%AE%9E%E8%AF%81%E4%B8%8E%E5%9F%BA%E5%B7%AE%22%5D%20--%3E%20Q%5B%22%2Fquant%2Firp%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<p>相对 PPP 慢、UIP 快，是短期 \\(q\\) 波动的来源：资产市场立刻改 \\(E\\)，物价粘住。巴拉萨–萨缪尔森解释 \\(q\\) 的趋势水平，不解释周度 UIP 残差。</p><h3 id="三角不要混层" tabindex="-1">三角不要混层 <a class="header-anchor" href="#三角不要混层" aria-label="Permalink to &quot;三角不要混层&quot;">​</a></h3><p><a href="/econ/impossible-trinity">不可能三角</a>约束的是政策目标集合：独立货币、钉住、资本开放。CIP 约束的是报价一致性。Rey 的全球金融周期称浮动也买不到完全独立——那是宏观边界修正，仍不要用某个基差数字来「证明」三角作废。本课禁止把限价簿深度写成开放宏观的定理。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>CIP 的机制是复制：借本币、买即期、存外币、卖远期，应对齐本币存款。UIP 的机制是风险：未对冲的外汇头寸在坏状态下可能亏，利率差可以是溢价而不是预期贬值。凯恩斯已经把远期当利率差的反映，而不是对未来即期的投票。长期货币中性与相对 PPP 仍锚定 \\(\\Delta\\ln E\\) 的通胀差部分；UIP 失败不取消这条慢锚。</p><p>政策含义：钉住加开放资本，UIP 要求 \\(i\\) 贴近 \\(i^*\\)，否则要么储备流动，要么钉住不可信（\\(\\mathbb{E}\\Delta e\\neq 0\\)）。浮动则让 \\(\\mathbb{E}\\Delta e\\) 吸收 \\(i\\) 差。这些句子在蒙代尔课展开；本课只把平价对象分清。巴拉萨–萨缪尔森解释 \\(q\\) 的趋势，不解释为何高息货币在样本里常常不按 UIP 贬值——那句实证属于 <code>/quant/irp</code> 的 Fama 回归，本课不报斜率。</p><p>突然停止发生时，违约风险与管制让复制中断，CIP 的宏观教学式不再把 \\(i\\) 钉死。那是制度碰撞，仍不要用某个基差数字代替三角。</p>',7)),(E(),r(p,null,{default:e(()=>[o(t,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E5%80%9F%E5%85%A5%E6%9C%AC%E5%B8%81%EF%BC%9A1%2Bi%22%5D%20--%3E%20B%5B%22%E5%8D%B3%E6%9C%9F%E4%B9%B0%E5%85%A5%E5%A4%96%E5%B8%81%EF%BC%9A%E6%8C%89%20S%20%E6%88%90%E4%BA%A4%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%AD%98%E5%A4%96%E5%B8%81%EF%BC%9A%E5%BE%97%201%2Bi*%22%5D%0A%20%20C%20--%3E%20D%5B%22%E8%BF%9C%E6%9C%9F%E5%8D%96%E5%87%BA%EF%BC%9A%E9%94%81%E5%AE%9A%20F%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%88%B0%E6%9C%9F%E6%9C%AC%E5%B8%81%EF%BC%9AF(1%2Bi*)%2FS%22%5D%0A%20%20E%20--%3E%20F%7B%22%E4%B8%8E%201%2Bi%20%E6%AF%94%E5%A4%A7%E5%B0%8F%22%7D%0A%20%20F%20--%20%22%E5%81%8F%E9%AB%98%E6%88%96%E5%81%8F%E4%BD%8E%22%20--%3E%20G%5B%22%E5%A5%97%E5%88%A9%E8%B5%84%E9%87%91%E8%BF%9B%E5%87%BA%EF%BC%8CF%20%E8%A2%AB%E6%8E%A8%E5%9B%9E%22%5D%0A%20%20F%20--%20%22%E7%9B%B8%E7%AD%89%22%20--%3E%20H%5B%22CIP%20%E6%88%90%E7%AB%8B%EF%BC%8C%E6%97%A0%E8%B6%85%E9%A2%9D%E6%94%B6%E7%9B%8A%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i('<p><span class="marginnote">术语先行：「即期」是今天成交、一两个工作日内交割的汇率；「远期」是今天签合同、约定未来某天按锁定价交割的汇率。远期价在屏幕上就在即期旁边，但它不是预测，而是报价台按两条利率算出来的对冲价格。</span></p><p><span class="marginnote">数字实例：设即期 \\(S=7\\)，本币一年利率 \\(4\\%\\)，外币 \\(2\\%\\)，则一年期远期 \\(F \\approx 7 \\times 1.04 / 1.02 \\approx 7.14\\)。远期本币升水约 \\(2\\%\\)，正好等于利差——这就是 \\(F=S(1+i)/(1+i^*)\\) 的含义。</span></p><p><span class="marginnote">常见误区：初学者容易把「借低息货币、存高息货币」当成无风险套息。实际上这笔头寸没买远期对冲，赚的是 UIP 假设里的风险溢价；坏状态一来（危机时高息货币急贬），几个月攒的利息可能一次亏光。有远期对冲的版本收益立刻被 CIP 抹平。</span></p><p><span class="marginnote">不可兑换、NDF、资本管制下，CIP 的检验对象已经换了。那不是宏观课用存款利率写的那条会计。细节见 <code>/quant/irp</code>。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在此报告 Fama 斜率，不要发明交叉货币基差的基点。不要把套息策略写成宏观主干。公司如何对冲外币债，接到原罪课；微观执行接到量化栏。后课默认：开放宏观用 UIP 当教学资产均衡，CIP 当无套利参照；证据与报价层不在本栏重做。</p><p>下一课：资本流动与利率把 IS–LM 拉到开放，静态预期下 \\(i=i^*\\) 是 UIP 的退化。Dornbusch 再把理性预期补回，超调用的仍是 UIP，不是 CIP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CIP 是抛补复制；UIP 是无抛补期望假说。</li><li>远期由 CIP 钉住，不是 UIP 的「预测」。</li><li>宏观用平价接 \\(i\\) 与 \\(E\\)；实证与基差见 <code>/quant/irp</code>。</li><li>不重写限价簿，不编基差数字。</li><li>钉住加开放时教学上 \\(i\\) 贴近 \\(i^*\\)，来自 UIP 而非 CIP。</li><li>出处：Keynes, <em>A Tract on Monetary Reform</em>, 1923。</li></ul>',9))])}const _=l(B,[["render",P]]);export{h as __pageData,_ as default};
